{"file_path":"src/render.js","content":"import { byName } from './graph.js'

function total(timings) {
  let t = 0
  for (const timing of timings.values()) t = Math.max(t, timing.finish)
  return t
}

export function renderWaves(tasks, depths, timings) {
  const waves = []
  for (const [name, d] of depths) {
    if (!waves[d]) waves[d] = []
    waves[d].push(name)
  }

  let out = ''
  for (let w = 0; w < waves.length; w++) {
    const names = (waves[w] || []).sort(byName)
    out += `wave ${w}: ${names.join(' ')}\n`
  }
  return out + `total ${total(timings)}\n`
}

export function renderExplain(tasks, depths, timings) {
  let out = ''
  for (const name of Array.from(tasks.keys()).sort(byName)) {
    const { start, finish } = timings.get(name)
    out += `${name} start=${start} finish=${finish} depth=${depths.get(name)}\n`
  }
  return out + `total ${total(timings)}\n`
}

/**
 * List scheduling: at each instant, fill every free worker with the ready task
 * of greatest priority, ties broken by ascending name.
 */
export function renderPack(tasks, dependencies, priorities, workerCount) {
  const workers = []
  for (let i = 0; i < workerCount; i++) workers.push({ free: 0, runs: [] })

  const finish = new Map() // name -> finish, once started
  const pending = new Set(tasks.keys())
  let time = 0

  while (pending.size > 0) {
    for (;;) {
      const worker = workers.find(w => w.free <= time)
      if (!worker) break

      let best = null
      for (const name of pending) {
        let ready = true
        for (const dep of dependencies.get(name) || []) {
          if (!finish.has(dep) || finish.get(dep) > time) {
            ready = false
            break
          }
        }
        if (!ready) continue
        if (
          best === null ||
          priorities.get(name) > priorities.get(best) ||
          (priorities.get(name) === priorities.get(best) && byName(name, best) < 0)
        ) {
          best = name
        }
      }
      if (best === null) break

      const end = time + tasks.get(best).cost
      worker.runs.push(`${best}@${time}-${end}`)
      worker.free = end
      finish.set(best, end)
      pending.delete(best)
    }

    if (pending.size === 0) break

    let next = Infinity
    for (const worker of workers) {
      if (worker.free > time) next = Math.min(next, worker.free)
    }
    if (next === Infinity) break // nothing can ever start
    time = next
  }

  let out = ''
  let makespan = 0
  for (let i = 0; i < workers.length; i++) {
    const runs = workers[i].runs
    out += `worker ${i}:` + runs.map(r => ' ' + r).join('') + '\n'
  }
  for (const end of finish.values()) makespan = Math.max(makespan, end)
  return out + `makespan ${makespan}\n`
}
"}

