{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { parseArgs } from './args.js'
import { parseInput } from './parse.js'
import { findCycle, computeDepths, computeTimings, computePriorities, byName } from './graph.js'
import { renderWaves, renderExplain, renderPack } from './render.js'

function fail(message, code) {
  process.stderr.write(message + '\n')
  process.exitCode = code
}

async function readStdin() {
  let input = ''
  process.stdin.setEncoding('utf8')
  for await (const chunk of process.stdin) input += chunk
  return input
}

async function main() {
  const argv = process.argv.slice(2)

  const args = parseArgs(argv)
  if (args.error) return fail(args.error, 2)

  const input = await readStdin()

  const parsed = parseInput(input)
  if (parsed.error) return fail(parsed.error, 2)

  const { tasks, dependencies } = parsed

  const cycle = findCycle(tasks, dependencies)
  if (cycle) return fail('error: cycle: ' + cycle.join(' -> '), 3)

  if (args.command === 'waves') {
    const depths = computeDepths(tasks, dependencies)
    const timings = computeTimings(tasks, dependencies)
    process.stdout.write(renderWaves(tasks, depths, timings))
  } else if (args.command === 'explain') {
    const depths = computeDepths(tasks, dependencies)
    const timings = computeTimings(tasks, dependencies)
    process.stdout.write(renderExplain(tasks, depths, timings))
  } else {
    const priorities = computePriorities(tasks, dependencies)
    process.stdout.write(renderPack(tasks, dependencies, priorities, args.workers))
  }
}

main().catch(err => {
  process.stderr.write(`error: ${err && err.message ? err.message : String(err)}\n`)
  process.exitCode = 2
})

export { byName }
"}

{"file_path":"src/args.js","content":"const USAGE = 'error: usage: cli.js waves|explain|pack <workers>'

/**
 * Validate the command line. Returns `{ command, workers }` or `{ error }`.
 */
export function parseArgs(argv) {
  if (argv.length === 0) return { error: USAGE }

  const command = argv[0]

  if (command === 'waves' || command === 'explain') {
    if (argv.length !== 1) return { error: USAGE }
    return { command }
  }

  if (command === 'pack') {
    if (argv.length !== 2) return { error: USAGE }
    const workers = argv[1]
    if (!/^[1-9][0-9]*$/.test(workers)) {
      return { error: 'error: workers must be a positive integer' }
    }
    return { command, workers: Number(workers) }
  }

  return { error: USAGE }
}
"}

{"file_path":"src/parse.js","content":"const NAME = /^[A-Za-z0-9_.-]+$/
const COST = /^[0-9]+$/

/**
 * Read the build graph text. Returns `{ tasks, dependencies }` or `{ error }`.
 *
 * `tasks` maps a name to `{ name, cost }`; `dependencies` maps a name to the
 * set of names it depends on.
 */
export function parseInput(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const tasks = new Map()
  const dependencies = new Map()
  const used = [] // every name a dep line mentions, in input order

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue

    const words = line.split(/\s+/)
    const n = i + 1
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        return { error: `error: line ${n}: expected task <name> <cost>` }
      }
      const name = words[1]
      const cost = words[2]
      if (!NAME.test(name)) {
        return { error: `error: line ${n}: invalid task name ${name}` }
      }
      if (!COST.test(cost)) {
        return { error: `error: line ${n}: cost must be a non-negative integer` }
      }
      if (tasks.has(name)) {
        return { error: `error: line ${n}: task ${name} is declared twice` }
      }
      tasks.set(name, { name, cost: Number(cost) })
    } else if (directive === 'dep') {
      if (words.length < 3) {
        return { error: `error: line ${n}: expected dep <name> <dependency>...` }
      }
      for (let w = 1; w < words.length; w++) {
        if (!NAME.test(words[w])) {
          return { error: `error: line ${n}: invalid task name ${words[w]}` }
        }
        used.push(words[w])
      }
      const name = words[1]
      let set = dependencies.get(name)
      if (!set) {
        set = new Set()
        dependencies.set(name, set)
      }
      for (let w = 2; w < words.length; w++) set.add(words[w])
    } else {
      return { error: `error: line ${n}: unknown directive ${directive}` }
    }
  }

  for (const name of used) {
    if (!tasks.has(name)) return { error: `error: unknown task ${name}` }
  }

  return { tasks, dependencies }
}
"}

