const VALID_NAME_CHARS = /^[A-Za-z0-9_.\-]+$/

/**
 * Parse command-line arguments
 */
function parseArgs(args) {
  if (args.length === 0) {
    return { error: 'usage: cli.js waves|explain|pack <workers>' }
  }

  const command = args[0]

  if (command === 'waves' || command === 'explain') {
    if (args.length !== 1) {
      return { error: 'usage: cli.js waves|explain|pack <workers>' }
    }
    return { command }
  } else if (command === 'pack') {
    if (args.length !== 2) {
      return { error: 'usage: cli.js waves|explain|pack <workers>' }
    }
    const workerCount = args[1]
    // Validate worker count: positive integer without sign or leading zero
    if (!/^[1-9]\d*$/.test(workerCount)) {
      return { error: 'workers must be a positive integer' }
    }
    return { command, workers: parseInt(workerCount, 10) }
  } else {
    return { error: 'usage: cli.js waves|explain|pack <workers>' }
  }
}

/**
 * Parse input from stdin
 */
function parseInput(input) {
  const lines = input.split('\n')
  // Drop the empty tail from a trailing newline
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  const tasks = new Map() // name -> { name, cost }
  const dependencies = new Map() // name -> Set of dependencies

  for (let lineNum = 0; lineNum < lines.length; lineNum++) {
    let line = lines[lineNum].trim()

    // Ignore empty lines and comments
    if (!line || line.startsWith('#')) {
      continue
    }

    const words = line.split(/\s+/)
    if (words.length === 0) continue

    const directive = words[0]
    const lineNumber = lineNum + 1

    if (directive === 'task') {
      if (words.length !== 3) {
        return {
          error: `error: line ${lineNumber}: expected task <name> <cost>`,
          code: 2,
        }
      }

      const name = words[1]
      const costStr = words[2]

      // Validate task name
      if (!VALID_NAME_CHARS.test(name)) {
        return {
          error: `error: line ${lineNumber}: invalid task name ${name}`,
          code: 2,
        }
      }

      // Validate cost
      if (!/^\d+$/.test(costStr)) {
        return {
          error: `error: line ${lineNumber}: cost must be a non-negative integer`,
          code: 2,
        }
      }

      const cost = parseInt(costStr, 10)

      // Check for duplicate task
      if (tasks.has(name)) {
        return {
          error: `error: line ${lineNumber}: task ${name} is declared twice`,
          code: 2,
        }
      }

      tasks.set(name, { name, cost })
    } else if (directive === 'dep') {
      if (words.length < 3) {
        return {
          error: `error: line ${lineNumber}: expected dep <name> <dependency>...`,
          code: 2,
        }
      }

      const name = words[1]
      const deps = words.slice(2)

      if (!dependencies.has(name)) {
        dependencies.set(name, new Set())
      }

      for (const dep of deps) {
        dependencies.get(name).add(dep)
      }
    } else {
      return {
        error: `error: line ${lineNumber}: unknown directive ${directive}`,
        code: 2,
      }
    }
  }

  // Check for unknown tasks in dependencies
  for (const [name, deps] of dependencies.entries()) {
    for (const dep of deps) {
      if (!tasks.has(dep)) {
        return {
          error: `error: unknown task ${dep}`,
          code: 2,
        }
      }
    }
  }

  return {
    tasks,
    dependencies,
  }
}

/**
 * Detect cycles using DFS
 */
function detectCycles(tasks, dependencies) {
  const visited = new Set()
  const recursionStack = new Set()
  const path = []

  function dfs(node) {
    visited.add(node)
    recursionStack.add(node)
    path.push(node)

    const deps = dependencies.get(node) || new Set()
    const sortedDeps = Array.from(deps).sort()

    for (const dep of sortedDeps) {
      if (!visited.has(dep)) {
        const cycle = dfs(dep)
        if (cycle) return cycle
      } else if (recursionStack.has(dep)) {
        // Found a cycle
        const cycleStart = path.indexOf(dep)
        const cycle = path.slice(cycleStart)
        cycle.push(dep) // repeat the first node at the end
        return cycle
      }
    }

    path.pop()
    recursionStack.delete(node)
    return null
  }

  // Check each task in ascending name order
  const sortedTasks = Array.from(tasks.keys()).sort()
  for (const task of sortedTasks) {
    visited.clear()
    recursionStack.clear()
    path.length = 0

    const cycle = dfs(task)
    if (cycle) {
      return cycle
    }
  }

  return null
}

/**
 * Compute task depths (waves) and timing info
 */
function computeTimings(tasks, dependencies) {
  const depth = new Map()
  const finishTimes = new Map()

  function computeDepth(node, visiting = new Set()) {
    if (depth.has(node)) {
      return depth.get(node)
    }

    if (visiting.has(node)) {
      return -1 // cycle detected (should be checked separately)
    }

    visiting.add(node)

    const deps = dependencies.get(node) || new Set()
    let maxDepth = -1

    for (const dep of deps) {
      const depDepth = computeDepth(dep, visiting)
      maxDepth = Math.max(maxDepth, depDepth)
    }

    visiting.delete(node)

    const taskDepth = maxDepth + 1
    depth.set(node, taskDepth)
    return taskDepth
  }

  // Compute depths for all tasks
  for (const task of tasks.keys()) {
    computeDepth(task)
  }

  // Compute start and finish times
  function computeTiming(node) {
    if (finishTimes.has(node)) {
      return finishTimes.get(node).finish
    }

    const deps = dependencies.get(node) || new Set()

    let startTime = 0
    for (const dep of deps) {
      const depFinish = computeTiming(dep)
      startTime = Math.max(startTime, depFinish)
    }

    const finishTime = startTime + tasks.get(node).cost
    finishTimes.set(node, { start: startTime, finish: finishTime })
    return finishTime
  }

  for (const task of tasks.keys()) {
    computeTiming(task)
  }

  return { depth, finishTimes }
}

/**
 * Compute priority for a task (longest chain from this task downwards)
 */
function computePriorities(tasks, dependencies) {
  const priority = new Map()
  const memo = new Map()

  function computePriority(node) {
    if (memo.has(node)) {
      return memo.get(node)
    }

    let maxChain = 0
    const taskCost = tasks.get(node).cost

    // Find all tasks that depend on this task (reverse dependency)
    for (const [other, otherDeps] of dependencies.entries()) {
      if (otherDeps.has(node)) {
        const otherPriority = computePriority(other)
        maxChain = Math.max(maxChain, otherPriority)
      }
    }

    const result = taskCost + maxChain
    memo.set(node, result)
    return result
  }

  for (const task of tasks.keys()) {
    computePriority(task)
  }

  return memo
}

/**
 * Main program
 */
async function main() {
  const args = process.argv.slice(2)

  // Parse arguments
  const argParsing = parseArgs(args)
  if (argParsing.error) {
    process.stderr.write(`error: ${argParsing.error}\n`)
    process.exit(2)
  }

  // Read stdin
  let input = ''
  for await (const chunk of process.stdin) {
    input += chunk
  }

  // Parse input
  const parsing = parseInput(input)
  if (parsing.error) {
    process.stderr.write(parsing.error + '\n')
    process.exit(parsing.code || 2)
  }

  const { tasks, dependencies } = parsing

  // Detect cycles
  const cycle = detectCycles(tasks, dependencies)
  if (cycle) {
    const cycleStr = cycle.join(' -> ')
    process.stderr.write(`error: cycle: ${cycleStr}\n`)
    process.exit(3)
  }

  // Compute timings
  const { depth, finishTimes } = computeTimings(tasks, dependencies)

  // Execute command
  const command = argParsing.command
  const workers = argParsing.workers

  if (command === 'waves') {
    let output = ''
    const waveMap = new Map()

    for (const [name, d] of depth.entries()) {
      if (!waveMap.has(d)) {
        waveMap.set(d, [])
      }
      waveMap.get(d).push(name)
    }

    const maxWave = waveMap.size === 0 ? -1 : Math.max(...waveMap.keys())

    for (let w = 0; w <= maxWave; w++) {
      const waveTasks = waveMap.get(w) || []
      waveTasks.sort()
      output += `wave ${w}: ${waveTasks.join(' ')}\n`
    }

    // Compute total makespan
    let total = 0
    for (const [name, timing] of finishTimes.entries()) {
      total = Math.max(total, timing.finish)
    }

    output += `total ${total}\n`
    process.stdout.write(output)
  } else if (command === 'explain') {
    let output = ''

    // Sort tasks by name
    const sortedTasks = Array.from(tasks.keys()).sort()

    for (const name of sortedTasks) {
      const timing = finishTimes.get(name)
      const d = depth.get(name)
      output += `${name} start=${timing.start} finish=${timing.finish} depth=${d}\n`
    }

    // Compute total makespan
    let total = 0
    for (const [name, timing] of finishTimes.entries()) {
      total = Math.max(total, timing.finish)
    }

    output += `total ${total}\n`
    process.stdout.write(output)
  } else if (command === 'pack') {
    // Simulate scheduling on workers
    const priorities = computePriorities(tasks, dependencies)

    // Track when each task finishes (after scheduling)
    const taskFinishTimes = new Map()
    const finished = new Set()
    const workerState = Array.from({ length: workers }, (_, i) => ({
      id: i,
      free: 0,
      tasks: [],
    }))

    let time = 0
    let hasWork = true

    while (hasWork && finished.size < tasks.size) {
      hasWork = false

      // Find all ready tasks (all dependencies finished at or before current time)
      const ready = []

      for (const [name, task] of tasks.entries()) {
        if (finished.has(name)) continue

        const deps = dependencies.get(name) || new Set()
        let allDepsFinished = true

        for (const dep of deps) {
          // A dependency must be in taskFinishTimes (scheduled) and finished by current time
          if (!taskFinishTimes.has(dep) || taskFinishTimes.get(dep) > time) {
            allDepsFinished = false
            break
          }
        }

        if (allDepsFinished) {
          ready.push(name)
        }
      }

      // Sort ready tasks by priority (descending) then by name (ascending)
      ready.sort((a, b) => {
        const priorityDiff = priorities.get(b) - priorities.get(a)
        if (priorityDiff !== 0) return priorityDiff
        return a.localeCompare(b)
      })

      // Assign ready tasks to free workers
      for (const taskName of ready) {
        // Find the worker with the smallest index that is free at current time
        const freeWorker = workerState.find(w => w.free <= time)

        if (!freeWorker) break

        hasWork = true
        const cost = tasks.get(taskName).cost

        // Start time must respect both worker availability and dependency finish times
        let start = freeWorker.free
        const deps = dependencies.get(taskName) || new Set()
        for (const dep of deps) {
          const depFinishTime = taskFinishTimes.get(dep) || 0
          start = Math.max(start, depFinishTime)
        }

        const finish = start + cost

        freeWorker.tasks.push({ name: taskName, start, finish })
        freeWorker.free = finish
        taskFinishTimes.set(taskName, finish)
        finished.add(taskName)
      }

      if (finished.size < tasks.size && !hasWork) {
        // No more tasks can be assigned at this time
        // Advance time to the next worker free time
        let nextTime = Infinity
        for (const worker of workerState) {
          if (worker.free > time) {
            nextTime = Math.min(nextTime, worker.free)
          }
        }
        if (nextTime !== Infinity) {
          time = nextTime
          hasWork = true
        }
      }
    }

    // Output results
    let output = ''
    let makespan = 0

    for (const worker of workerState) {
      output += `worker ${worker.id}:`
      for (const task of worker.tasks) {
        output += ` ${task.name}@${task.start}-${task.finish}`
        makespan = Math.max(makespan, task.finish)
      }
      output += '\n'
    }

    output += `makespan ${makespan}\n`
    process.stdout.write(output)
  }
}

main().catch(err => {
  process.stderr.write(`error: ${err.message}\n`)
  process.exit(2)
})

