const COST = /^[0-9]+$/

/**
 * Read the build graph text. Returns `{ tasks, dependencies }` or `{ error }`.
 *
 * `tasks` maps a name to `{ name, cost }`; `dependencies` maps a name to the
 * set of names it depends on.
 */
export function parseInput(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const tasks = new Map()
  const dependencies = new Map()
  const used = [] // every name a dep line mentions, in input order

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue

    const words = line.split(/\s+/)
    const n = i + 1
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        return { error: `error: line ${n}: expected task <name> <cost>` }
      }
      const name = words[1]
      const cost = words[2]
      if (!NAME.test(name)) {
        return { error: `error: line ${n}: invalid task name ${name}` }
      }
      if (!COST.test(cost)) {
        return { error: `error: line ${n}: cost must be a non-negative integer` }
      }
      if (tasks.has(name)) {
        return { error: `error: line ${n}: task ${name} is declared twice` }
      }
      tasks.set(name, { name, cost: Number(cost) })
    } else if (directive === 'dep') {
      if (words.length < 3) {
        return { error: `error: line ${n}: expected dep <name> <dependency>...` }
      }
      for (let w = 1; w < words.length; w++) {
        if (!NAME.test(words[w])) {
          return { error: `error: line ${n}: invalid task name ${words[w]}` }
        }
        used.push(words[w])
      }
      const name = words[1]
      let set = dependencies.get(name)
      if (!set) {
        set = new Set()
        dependencies.set(name, set)
      }
      for (let w = 2; w < words.length; w++) set.add(words[w])
    } else {
      return { error: `error: line ${n}: unknown directive ${directive}` }
    }
  }

  for (const name of used) {
    if (!tasks.has(name)) return { error: `error: unknown task ${name}` }
  }

  return { tasks, dependencies }
}
