{"file_path":"src/graph.js","content":"/** Ascending order on the raw characters of a name. */
export function byName(a, b) {
  return a < b ? -1 : a > b ? 1 : 0
}

function depsOf(dependencies, name) {
  const set = dependencies.get(name)
  return set ? Array.from(set).sort(byName) : []
}

/**
 * The first cycle a depth-first search finds, starting from each task in
 * ascending name order and walking each task's dependencies in ascending name
 * order. Returns the names of the cycle, the first one repeated at the end, or
 * null when the graph is acyclic.
 */
export function findCycle(tasks, dependencies) {
  const done = new Set()
  const onStack = new Set()
  const roots = Array.from(tasks.keys()).sort(byName)

  for (const root of roots) {
    if (done.has(root)) continue

    // Iterative depth-first search so that deep graphs do not overflow.
    const path = [root]
    const cursor = [0]
    onStack.add(root)

    while (path.length > 0) {
      const node = path[path.length - 1]
      const deps = depsOf(dependencies, node)
      const i = cursor[cursor.length - 1]

      if (i < deps.length) {
        cursor[cursor.length - 1] = i + 1
        const dep = deps[i]
        if (onStack.has(dep)) {
          const cycle = path.slice(path.indexOf(dep))
          cycle.push(dep)
          return cycle
        }
        if (!done.has(dep)) {
          path.push(dep)
          cursor.push(0)
          onStack.add(dep)
        }
      } else {
        onStack.delete(node)
        done.add(node)
        path.pop()
        cursor.pop()
      }
    }
  }

  return null
}

/** A reverse topological order: every task comes after its dependencies. */
function topoOrder(tasks, dependencies) {
  const order = []
  const seen = new Set()

  for (const root of Array.from(tasks.keys()).sort(byName)) {
    if (seen.has(root)) continue
    const path = [root]
    const cursor = [0]
    seen.add(root)
    while (path.length > 0) {
      const node = path[path.length - 1]
      const deps = depsOf(dependencies, node)
      const i = cursor[cursor.length - 1]
      if (i < deps.length) {
        cursor[cursor.length - 1] = i + 1
        const dep = deps[i]
        if (!seen.has(dep)) {
          seen.add(dep)
          path.push(dep)
          cursor.push(0)
        }
      } else {
        order.push(node)
        path.pop()
        cursor.pop()
      }
    }
  }

  return order
}

/** The wave each task sits in: one more than its deepest dependency. */
export function computeDepths(tasks, dependencies) {
  const depth = new Map()
  for (const name of topoOrder(tasks, dependencies)) {
    let max = -1
    for (const dep of depsOf(dependencies, name)) {
      max = Math.max(max, depth.get(dep))
    }
    depth.set(name, max + 1)
  }
  return depth
}

/** The start and finish of every task with unlimited workers. */
export function computeTimings(tasks, dependencies) {
  const timings = new Map()
  for (const name of topoOrder(tasks, dependencies)) {
    let start = 0
    for (const dep of depsOf(dependencies, name)) {
      start = Math.max(start, timings.get(dep).finish)
    }
    timings.set(name, { start, finish: start + tasks.get(name).cost })
  }
  return timings
}

/** The cost of the longest chain that begins at each task. */
export function computePriorities(tasks, dependencies) {
  const dependents = new Map()
  for (const name of tasks.keys()) dependents.set(name, [])
  for (const [name, deps] of dependencies) {
    for (const dep of deps) dependents.get(dep).push(name)
  }

  const priority = new Map()
  // Dependencies come first in the topological order, so walk it backwards:
  // every dependent of a task is settled before the task itself.
  const order = topoOrder(tasks, dependencies)
  for (let i = order.length - 1; i >= 0; i--) {
    const name = order[i]
    let tail = 0
    for (const other of dependents.get(name)) {
      tail = Math.max(tail, priority.get(other))
    }
    priority.set(name, tasks.get(name).cost + tail)
  }
  return priority
}
